import assert from 'node:assert/strict';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { writeFile } from 'node:fs/promises';
import { FakeClock } from '../../.test-build/tests/fake-clock.js';
const directory = process.argv[2];
const label = process.argv[3];
const count = 200000;
const { Command, Controller, Module } = await import(pathToFileURL(resolve(directory, 'index.js')).href);
const { Application } = await import(pathToFileURL(resolve(directory, 'core/application.js')).href);
class Commands { run() {} }
Controller()(Commands);
Command('run')(Commands.prototype, 'run', Object.getOwnPropertyDescriptor(Commands.prototype, 'run'));
class Root {}
Module({controllers:[Commands]})(Root);
const clock = new FakeClock();
const app = await Application.create(Root, {
  appId:'fixture',secret:'fixture-secret',
  execution:{dedupMaxEntries:count,replyScopeMaxEntries:count,dedupTtlMs:3600000,replyScopeTtlMs:3600000},
  logger:{debug(){},info(){},warn(){},error(){}},
},{clock,transport:()=>({start:async()=>{},stop:async()=>{}}),fetch:async()=>Response.json({access_token:'fixture',expires_in:7200})});
await app.start();
const event = (id)=>({op:0,t:'GROUP_MESSAGE_CREATE',d:{id,group_openid:'group',author:{member_openid:'user'},content:'/run'}});
let reads = 0;
try {
 for(let i=0;i<count;i++) {
  const r=app.execution.accept(event(String(i)),128);assert.equal(r.status,'accepted');await r.done;
  await clock.advance(1);
 }
 global.gc?.();
 const retainedMemory=process.memoryUsage();
 await clock.advance(3600000-count);
 const start=performance.now();
 for(let i=0;i<1000;i++) {
  const r=app.execution.accept(event('new-'+i),128);assert.equal(r.status,'accepted');await r.done;
  await clock.advance(1);
 }
 const expiryDurationMs=performance.now()-start;
 for(const name of ['dedup','scopes']) for(const entry of Reflect.get(app.execution,name).values()) {
   let value=entry.expiresAt;
   Object.defineProperty(entry,'expiresAt',{get(){reads++;return value},set(next){value=next}});
 }
 const r=app.execution.accept(event('last'),128);assert.equal(r.status,'accepted');await r.done;
 const report={label,node:process.version,count,measuredExpirations:1000,expiryDurationMs,expiryReadsPerArrival:reads,retainedMemory};
 await writeFile('work/capacity-review/expiry-'+label+'.json',JSON.stringify(report,null,2)+'\n');
 console.log(report);
} finally {await app.close();}
assert.equal(clock.pending,0);
